import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.logging.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.util.*;
import java.nio.charset.StandardCharsets;

public class SecureJobWorker {
    private static final Logger logger = Logger.getLogger(SecureJobWorker.class.getName());
    private static final int FAILURE_THRESHOLD = 5;
    private static final long RECOVERY_TIMEOUT_MS = 30000;
    private static final int MAX_RETRY = 3;

    private final ExecutorService executor = Executors.newFixedThreadPool(4);
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(2);
    private final AtomicInteger failureCount = new AtomicInteger(0);
    private final AtomicLong lastFailureTime = new AtomicLong(0);
    private final AtomicReference<CircuitState> state = new AtomicReference<>(CircuitState.CLOSED);
    private final ConcurrentLinkedQueue<JobContext> retryQueue = new ConcurrentLinkedQueue<>();
    private final Map<String, JobContext> activeJobs = new ConcurrentHashMap<>();

    enum CircuitState { CLOSED, OPEN, HALF_OPEN }

    static class JobContext {
        final String jobId;
        final byte[] encryptedPayload;
        final byte[] decryptionKey;
        final int attemptCount;
        final long createdAt;
        private volatile boolean cleared = false;

        JobContext(String jobId, byte[] encryptedPayload, byte[] decryptionKey, int attemptCount) {
            this.jobId = jobId;
            this.encryptedPayload = encryptedPayload;
            this.decryptionKey = Arrays.copyOf(decryptionKey, decryptionKey.length);
            this.attemptCount = attemptCount;
            this.createdAt = System.currentTimeMillis();
        }

        JobContext withIncrementedAttempt() {
            return new JobContext(this.jobId, this.encryptedPayload, this.decryptionKey, this.attemptCount + 1);
        }

        void clearSensitive() {
            Arrays.fill(this.decryptionKey, (byte) 0);
            this.cleared = true;
        }
    }

    public void submitJob(String jobId, byte[] encryptedPayload, byte[] key) {
        JobContext ctx = new JobContext(jobId, encryptedPayload, key, 0);
        activeJobs.put(jobId, ctx);
        executor.submit(() -> processJob(ctx));
    }

    private void processJob(JobContext ctx) {
        if (!canExecute()) {
            handleCircuitOpen(ctx);
            return;
        }

        try {
            String result = decryptAndProcess(ctx);
            onSuccess(ctx, result);
        } catch (Exception e) {
            onFailure(ctx, e);
        }
    }

    private String decryptAndProcess(JobContext ctx) throws Exception {
        SecretKeySpec keySpec = new SecretKeySpec(ctx.decryptionKey, "AES");
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        byte[] iv = Arrays.copyOfRange(ctx.encryptedPayload, 0, 12);
        GCMParameterSpec gcmSpec = new GCMParameterSpec(128, iv);
        cipher.init(Cipher.DECRYPT_MODE, keySpec, gcmSpec);
        byte[] ciphertext = Arrays.copyOfRange(ctx.encryptedPayload, 12, ctx.encryptedPayload.length);
        byte[] plaintext = cipher.doFinal(ciphertext);
        String content = new String(plaintext, StandardCharsets.UTF_8);
        Arrays.fill(plaintext, (byte) 0);
        try {
            return processBusinessLogic(content);
        } finally {
            content = null;
        }
    }

    private String processBusinessLogic(String data) throws Exception {
        if (data.contains("INVALID_MARKER")) {
            throw new RuntimeException("Processing failed: invalid data format");
        }
        return "processed:" + data.hashCode();
    }

    private void onSuccess(JobContext ctx, String result) {
        failureCount.set(0);
        state.set(CircuitState.CLOSED);
        logger.info("Job " + ctx.jobId + " completed: " + result);
        finalizeJob(ctx);
    }

    private void onFailure(JobContext ctx, Exception e) {
        int failures = failureCount.incrementAndGet();
        lastFailureTime.set(System.currentTimeMillis());
        logger.warning("Job " + ctx.jobId + " failed (attempt " + ctx.attemptCount + "): " + e.getMessage());

        if (failures >= FAILURE_THRESHOLD) {
            state.set(CircuitState.OPEN);
            logger.severe("Circuit breaker OPEN after " + failures + " failures");
        }

        if (ctx.attemptCount < MAX_RETRY) {
            scheduleRetry(ctx);
        } else {
            logger.severe("Job " + ctx.jobId + " exhausted retries, moving to dead letter");
            moveToDeadLetter(ctx);
        }
    }

    private void scheduleRetry(JobContext ctx) {
        JobContext retryCtx = ctx.withIncrementedAttempt();
        retryQueue.offer(retryCtx);
        activeJobs.put(ctx.jobId, retryCtx);
        scheduler.schedule(() -> {
            retryQueue.remove(retryCtx);
            processJob(retryCtx);
        }, (long) Math.pow(2, retryCtx.attemptCount) * 1000, TimeUnit.MILLISECONDS);
    }

    private void moveToDeadLetter(JobContext ctx) {
        logger.info("Dead letter: job " + ctx.jobId + " after " + ctx.attemptCount + " attempts");
        activeJobs.remove(ctx.jobId);
        ctx.clearSensitive();
    }

    private void finalizeJob(JobContext ctx) {
        activeJobs.remove(ctx.jobId);
        ctx.clearSensitive();
    }

    private void handleCircuitOpen(JobContext ctx) {
        logger.warning("Circuit open, queueing job " + ctx.jobId);
        retryQueue.offer(ctx);
    }

    private boolean canExecute() {
        CircuitState current = state.get();
        if (current == CircuitState.CLOSED) return true;
        if (current == CircuitState.OPEN) {
            long elapsed = System.currentTimeMillis() - lastFailureTime.get();
            if (elapsed > RECOVERY_TIMEOUT_MS) {
                state.compareAndSet(CircuitState.OPEN, CircuitState.HALF_OPEN);
                return true;
            }
            return false;
        }
        return true;
    }

    public Map<String, Object> getHealthStatus() {
        Map<String, Object> status = new LinkedHashMap<>();
        status.put("state", state.get().name());
        status.put("failureCount", failureCount.get());
        status.put("activeJobs", activeJobs.size());
        status.put("retryQueueSize", retryQueue.size());
        return status;
    }
}
